WITH cleaned AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, CASE WHEN pressure >= 1029 THEN 'High' WHEN pressure >= 988 THEN 'Medium' ELSE 'Low' END AS pressure_level FROM device_readings WHERE device_code = 'DV-03'), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessionized AS (SELECT id, device_code, reading_ts, pressure, pressure_level, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), gaps_2 AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM sessionized), sessionized_device_readings AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id_2 FROM gaps_2), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts DESC, id) AS row_num FROM sessionized_device_readings) x WHERE row_num = 1), latest_device_readings AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY burst_id DESC, id) AS row_num_2 FROM latest QUALIFY row_num_2 = 1), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 1 HOUR THEN 1 ELSE 0 END AS is_new_session FROM latest_device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT burst_id, DATE_TRUNC('HOUR', reading_ts) AS hour_window, SIZE(COLLECT_SET(device_code)) AS num_device_codes, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(burst_id), 2) AS avg_burst_id, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count FROM sessions_device_readings GROUP BY 1, 2 ORDER BY burst_id DESC;
